CREATE TABLE "report_generated_logs" ("id" integer primary key autoincrement not null, "agency_id" integer not null, "user_id" integer not null, "report_template_id" integer not null, "format" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("agency_id") references "agencies"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("report_template_id") references "report_templates"("id") on delete cascade);
CREATE TABLE "report_templates" ("id" integer primary key autoincrement not null, "agency_id" integer not null, "name" varchar not null, "type" varchar not null, "config" text not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "sort_order" integer not null default '0', foreign key("agency_id") references "agencies"("id") on delete cascade);
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "settings" ("id" integer primary key autoincrement not null, "agency_id" integer not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime, foreign key("agency_id") references "agencies"("id") on delete cascade);
CREATE TABLE "skills" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "sponsor_applicant" ("id" integer primary key autoincrement not null, "sponsor_id" integer not null, "applicant_id" integer not null, "selected_at" datetime, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("sponsor_id") references "sponsors"("id") on delete cascade, foreign key("applicant_id") references "applicants"("id") on delete cascade);
CREATE TABLE "sponsors" ("id" integer primary key autoincrement not null, "agency_id" integer not null, "id_number" varchar not null, "company_name" varchar not null, "contact_person" varchar, "email" varchar not null, "contact_no" varchar, "viber" varchar, "address" text, "city" varchar, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("agency_id") references "agencies"("id") on delete cascade);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE "starting_balances" ("id" integer primary key autoincrement not null, "agency_id" integer not null, "user_id" integer, "agent_id" integer, "applicant_id" integer, "date" date not null, "account" varchar not null default 'Starting Balance', "amount" numeric not null default '0', "particular" text, "created_at" datetime, "updated_at" datetime, foreign key("agency_id") references "agencies"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null, foreign key("agent_id") references "agents"("id") on delete set null, foreign key("applicant_id") references "applicants"("id") on delete set null);
CREATE TABLE "status_codes" ("id" integer primary key autoincrement not null, "code" integer not null, "label" varchar not null, "label_saudi" varchar, "description" text, "color" varchar, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "status_transitions" ("id" integer primary key autoincrement not null, "from_code" integer not null, "to_code" integer not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("from_code") references "status_codes"("code") on delete cascade, foreign key("to_code") references "status_codes"("code") on delete cascade);
CREATE TABLE "user_permissions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "permission" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "agency_id" integer, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "user_type" varchar not null default ('admin'), "status" varchar not null default ('active'), "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "employer_id" integer, "username" varchar, "locale" varchar not null default ('en'), "branch_id" integer, "middle_name" varchar, "surname" varchar, "contact" varchar, foreign key("employer_id") references employers("id") on delete set null on update no action, foreign key("agency_id") references agencies("id") on delete set null on update no action, foreign key("branch_id") references "branches"("id") on delete set null);
